// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;

    // The contract under test sends the FULL balance to Owner (= this test
    // contract) via `transfer`, which only forwards 2300 gas — the test
    // contract must be able to accept ETH or the call reverts.
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);

        // Fund the contract directly with an admissible positive balance.
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        uint256 ownerBefore = address(this).balance;

        // Owner is msg.sender of construction, i.e. this test contract.
        vm.prank(address(this));
        c.withdraw();

        // GENERAL RULE: withdrawing moves the contract's ENTIRE balance to the
        // owner — the owner gains exactly `amount` and the contract holds 0.
        // The mutant transfers only `amount - 1`, so for every positive amount
        // the owner gains one wei less and 1 wei stays in the contract.
        assertTrue(address(this).balance - ownerBefore == amount && address(c).balance == 0);
    }
}
